__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"suppressionDocument",{enumerable:!0,get:function(){return t}});var s=r(d[0]),n=r(d[1]);const t=(0,s.publishedDocument)({id:"suppression",slug:"suppression",title:"Suppression du compte et des donn\xe9es",shortTitle:"Suppression de compte",sections:[{heading:"1. Supprimer votre compte Croki",paragraphs:[`${n.LEGAL_OPERATOR_NAME}, \xe9diteur de ${n.LEGAL_TRADE_NAME}, permet aux utilisateurs disposant d\u2019un compte Croki d\u2019en demander la suppression.`,"La suppression d\u2019un compte est diff\xe9rente d\u2019une simple d\xe9connexion, suspension ou d\xe9sactivation temporaire.","Lorsqu\u2019une suppression est ex\xe9cut\xe9e, le compte ne doit plus permettre une utilisation normale de Croki et les donn\xe9es personnelles qui ne doivent plus \xeatre conserv\xe9es sont supprim\xe9es ou anonymis\xe9es.","Certaines donn\xe9es peuvent toutefois \xeatre conserv\xe9es lorsque leur conservation reste n\xe9cessaire pour respecter une obligation l\xe9gale, traiter une op\xe9ration en cours, pr\xe9venir la fraude ou constater, exercer ou d\xe9fendre des droits."]},{heading:"2. Depuis l\u2019application Croki",paragraphs:["Lorsqu\u2019un utilisateur est connect\xe9, la suppression du compte peut \xeatre initi\xe9e directement depuis Croki.","Pour un Client, la fonction est accessible depuis les param\xe8tres ou le profil du compte.","Pour un Professionnel, la fonction est accessible depuis les param\xe8tres de son Compte Pro.","Croki ne demande pas \xe0 l\u2019utilisateur de contacter obligatoirement le support, t\xe9l\xe9phoner ou envoyer un courrier simplement pour initier la suppression lorsqu\u2019il peut normalement utiliser son compte."]},{heading:"3. Depuis le Web sans l\u2019application",paragraphs:["La pr\xe9sente page constitue \xe9galement un point d\u2019entr\xe9e public permettant de demander la suppression d\u2019un compte Croki sans installer ou r\xe9installer l\u2019application.","Il n\u2019est pas n\xe9cessaire de disposer encore de l\u2019application Croki sur son appareil pour initier une demande.","Une personne qui ne peut plus se connecter doit pouvoir utiliser le formulaire public de demande de suppression ou contacter FOODTECH SOLUTIONS aux coordonn\xe9es indiqu\xe9es sur cette page.","FOODTECH SOLUTIONS effectue ensuite les v\xe9rifications raisonnablement n\xe9cessaires afin de s\u2019assurer que la demande concerne bien le compte de la personne qui l\u2019a d\xe9pos\xe9e."]},{heading:"4. Demande publique de suppression",paragraphs:["Le formulaire public de suppression permet notamment de communiquer l\u2019adresse \xe9lectronique associ\xe9e au compte et les informations n\xe9cessaires \xe0 l\u2019identification de la demande.","Le formulaire n\u2019ex\xe9cute pas imm\xe9diatement une suppression irr\xe9versible sur la seule base d\u2019une adresse \xe9lectronique saisie.","Une v\xe9rification est effectu\xe9e avant toute suppression afin d\u2019\xe9viter qu\u2019un tiers puisse supprimer frauduleusement le compte d\u2019une autre personne.","La cr\xe9ation ou la reconnexion \xe0 un compte Croki ne doit pas \xeatre impos\xe9e lorsqu\u2019une autre m\xe9thode proportionn\xe9e permet de v\xe9rifier l\u2019identit\xe9 du demandeur."]},{heading:"5. V\xe9rification de votre identit\xe9",paragraphs:["Croki doit v\xe9rifier suffisamment l\u2019identit\xe9 de la personne qui demande la suppression afin d\u2019\xe9viter les suppressions frauduleuses.","Lorsqu\u2019une demande est effectu\xe9e depuis une session Croki correctement authentifi\xe9e, cette authentification peut \xeatre utilis\xe9e pour contribuer \xe0 cette v\xe9rification.","Lorsqu\u2019une demande est effectu\xe9e depuis la page publique, Croki peut notamment v\xe9rifier l\u2019acc\xe8s \xe0 l\u2019adresse \xe9lectronique associ\xe9e au compte.","Une pi\xe8ce d\u2019identit\xe9 n\u2019est pas demand\xe9e syst\xe9matiquement.","Une information ou un justificatif suppl\xe9mentaire n\u2019est demand\xe9 qu\u2019en cas de doute raisonnable sur l\u2019identit\xe9 de la personne ou lorsque le niveau de risque de la demande le justifie."]},{heading:"6. Confirmation avant suppression",paragraphs:["Croki demande une confirmation explicite avant de proc\xe9der \xe0 une suppression irr\xe9versible du compte.","L\u2019interface explique les principales cons\xe9quences de la suppression avant que l\u2019utilisateur confirme sa d\xe9cision.","Croki peut demander une r\xe9authentification r\xe9cente ou un m\xe9canisme suppl\xe9mentaire de confirmation lorsqu\u2019il est n\xe9cessaire de prot\xe9ger le compte contre une suppression non autoris\xe9e.","Ces mesures de s\xe9curit\xe9 ne doivent pas \xeatre utilis\xe9es pour rendre artificiellement difficile la suppression d\u2019un compte."]},{heading:"7. Cons\xe9quences g\xe9n\xe9rales",paragraphs:["Apr\xe8s l\u2019ex\xe9cution de la suppression, le compte ne peut plus \xeatre utilis\xe9 normalement pour acc\xe9der aux fonctionnalit\xe9s qui lui \xe9taient associ\xe9es.","Les sessions actives et moyens d\u2019authentification contr\xf4l\xe9s par Croki sont r\xe9voqu\xe9s ou invalid\xe9s.","Les informations personnelles qui ne doivent plus \xeatre conserv\xe9es sont supprim\xe9es ou anonymis\xe9es.","Les acc\xe8s professionnels associ\xe9s au compte sont supprim\xe9s ou r\xe9voqu\xe9s lorsqu\u2019ils ne doivent plus exister.","La suppression ne constitue pas une simple mise en sommeil du compte destin\xe9e \xe0 conserver ind\xe9finiment toutes les donn\xe9es en arri\xe8re-plan."]},{heading:"8. Commandes en cours",paragraphs:["Une Commande en cours peut emp\xeacher l\u2019ex\xe9cution technique imm\xe9diate de la suppression lorsqu\u2019il est n\xe9cessaire de terminer, annuler ou s\xe9curiser cette op\xe9ration.","Sont notamment concern\xe9es les Commandes encore en attente d\u2019acceptation, accept\xe9es, en pr\xe9paration ou pr\xeates \xe0 \xeatre retir\xe9es.","Croki informe alors l\u2019utilisateur de la raison emp\xeachant la suppression imm\xe9diate et des \xe9tapes n\xe9cessaires pour finaliser la situation.","Cette limitation temporaire n\u2019emp\xeache pas l\u2019utilisateur de d\xe9poser une demande d\u2019effacement de ses donn\xe9es personnelles au titre du RGPD."]},{heading:"9. Compte Professionnel et Commandes en cours",paragraphs:["La suppression imm\xe9diate d\u2019un Compte Pro peut \xeatre diff\xe9r\xe9e lorsqu\u2019un ou plusieurs \xe9tablissements g\xe9r\xe9s par ce compte disposent encore de Commandes devant \xeatre ex\xe9cut\xe9es ou r\xe9gularis\xe9es.","Croki doit \xe9viter qu\u2019une suppression de compte entra\xeene l\u2019abandon d\u2019une Commande Client d\xe9j\xe0 engag\xe9e.","Les nouvelles Commandes peuvent \xeatre emp\xeach\xe9es lorsque cela est n\xe9cessaire pour permettre la fermeture ordonn\xe9e de l\u2019activit\xe9 du compte concern\xe9.","Les cons\xe9quences contractuelles de la fin de relation du Professionnel sont \xe9galement d\xe9crites dans les Conditions Pro."]},{heading:"10. Comptes administrateurs",paragraphs:["Les comptes disposant de privil\xe8ges administratifs font l\u2019objet de protections suppl\xe9mentaires en raison de leurs droits d\u2019acc\xe8s au Service.","Croki peut emp\xeacher la suppression automatique du dernier compte administrateur actif lorsque celle-ci rendrait impossible l\u2019administration s\xe9curis\xe9e de la plateforme.","Cette restriction op\xe9rationnelle n\u2019autorise pas FOODTECH SOLUTIONS \xe0 conserver ind\xe9finiment des donn\xe9es personnelles qui ne seraient plus n\xe9cessaires.","La situation doit \xeatre r\xe9gularis\xe9e, par exemple par le transfert pr\xe9alable des responsabilit\xe9s administratives, avant la fermeture d\xe9finitive du compte concern\xe9."]},{heading:"11. Donn\xe9es du profil",paragraphs:["Les donn\xe9es de profil qui ne sont plus n\xe9cessaires apr\xe8s la suppression du compte sont supprim\xe9es ou anonymis\xe9es.","Cela concerne notamment, selon le compte et les traitements encore n\xe9cessaires, le pr\xe9nom, le nom, le t\xe9l\xe9phone et les autres donn\xe9es de profil qui ne doivent plus \xeatre rattach\xe9es \xe0 une personne identifiable.","L\u2019adresse \xe9lectronique utilis\xe9e pour l\u2019authentification n\u2019est pas conserv\xe9e comme identifiant actif du compte lorsque sa conservation n\u2019est plus n\xe9cessaire.","Une r\xe9f\xe9rence technique pseudonymis\xe9e peut subsister lorsque son maintien est n\xe9cessaire pour assurer l\u2019int\xe9grit\xe9 de donn\xe9es historiques devant l\xe9galement ou l\xe9gitimement \xeatre conserv\xe9es."]},{heading:"12. Authentification et sessions",paragraphs:["Les sessions actives sont r\xe9voqu\xe9es lors de la suppression du compte.","Les jetons de rafra\xeechissement et autres moyens d\u2019authentification contr\xf4l\xe9s par Croki sont invalid\xe9s lorsqu\u2019ils ne doivent plus permettre l\u2019acc\xe8s au Service.","Le compte supprim\xe9 ne doit pas rester utilisable avec son ancien mot de passe ou une ancienne session encore valide.","Les secrets et donn\xe9es techniques devenus inutiles sont supprim\xe9s conform\xe9ment aux m\xe9canismes de s\xe9curit\xe9 applicables."]},{heading:"13. Favoris et pr\xe9f\xe9rences personnelles",paragraphs:["Les favoris associ\xe9s au Client sont supprim\xe9s lorsque le compte est supprim\xe9.","Les pr\xe9f\xe9rences personnelles stock\xe9es c\xf4t\xe9 serveur sont \xe9galement supprim\xe9es lorsqu\u2019elles ne doivent plus \xeatre conserv\xe9es.","Certaines donn\xe9es locales peuvent rester temporairement pr\xe9sentes sur un appareil d\xe9j\xe0 utilis\xe9 jusqu\u2019\xe0 la suppression des donn\xe9es de l\u2019application, du cache ou du stockage local.","Ces donn\xe9es locales ne doivent cependant plus permettre d\u2019acc\xe9der au compte supprim\xe9."]},{heading:"14. Notifications",paragraphs:["Les notifications internes associ\xe9es au compte sont supprim\xe9es lorsqu\u2019elles ne doivent plus \xeatre conserv\xe9es.","Les jetons de notification push li\xe9s \xe0 l\u2019installation et au compte sont r\xe9voqu\xe9s, dissoci\xe9s ou supprim\xe9s lorsqu\u2019ils ne sont plus n\xe9cessaires.","Un jeton devenu inutile apr\xe8s la suppression du compte ne doit pas \xeatre conserv\xe9 ind\xe9finiment simplement parce qu\u2019il appartenait \xe0 un ancien appareil."]},{heading:"15. Identifiants d\u2019appareil",paragraphs:["Les identifiants techniques d\u2019appareil associ\xe9s au compte sont supprim\xe9s ou dissoci\xe9s lorsqu\u2019ils ne sont plus n\xe9cessaires \xe0 une finalit\xe9 l\xe9gitime.","Pour les comptes Professionnels, les enregistrements utilis\xe9s pour les notifications de Commandes doivent \xeatre supprim\xe9s ou rendus inactifs lorsque le compte ou l\u2019appareil ne doit plus recevoir de notifications.","Un identifiant peut \xeatre temporairement conserv\xe9 lorsqu\u2019il reste n\xe9cessaire \xe0 la s\xe9curit\xe9, \xe0 la pr\xe9vention de la fraude ou \xe0 une investigation en cours, dans les limites pr\xe9vues par la Politique de confidentialit\xe9."]},{heading:"16. Commandes pass\xe9es",paragraphs:["La suppression du compte n\u2019entra\xeene pas n\xe9cessairement la suppression imm\xe9diate de l\u2019historique des Commandes qui doit encore \xeatre conserv\xe9.","Certaines donn\xe9es relatives aux Commandes peuvent \xeatre n\xe9cessaires \xe0 la preuve des contrats, \xe0 la comptabilit\xe9, \xe0 la fiscalit\xe9, aux remboursements, \xe0 la pr\xe9vention de la fraude ou au traitement de litiges.","Lorsque l\u2019identit\xe9 directe du Client n\u2019est plus n\xe9cessaire, Croki r\xe9duit ou anonymise les donn\xe9es concern\xe9es dans la mesure compatible avec les obligations de conservation restantes.","Les donn\xe9es ne sont pas conserv\xe9es ind\xe9finiment simplement parce qu\u2019elles appartiennent \xe0 une ancienne Commande."]},{heading:"17. Paiements et remboursements",paragraphs:["La suppression du compte n\u2019efface pas automatiquement les r\xe9f\xe9rences de paiement dont la conservation reste n\xe9cessaire \xe0 la preuve, \xe0 la comptabilit\xe9, aux remboursements, aux contestations ou aux obligations l\xe9gales.","Croki ne stocke pas les num\xe9ros complets de carte bancaire.","Stripe peut conserver certaines informations dans le cadre de ses propres obligations l\xe9gales et de paiement.","Lorsque FOODTECH SOLUTIONS agit comme responsable du traitement pour certaines donn\xe9es confi\xe9es \xe0 un prestataire, elle prend les mesures n\xe9cessaires afin que la suppression ou l\u2019anonymisation soit \xe9galement prise en compte par les prestataires concern\xe9s dans les conditions applicables."]},{heading:"18. Documents comptables et fiscaux",paragraphs:["Certaines pi\xe8ces comptables et justificatives ne peuvent pas \xeatre supprim\xe9es au seul motif que le compte Croki a \xe9t\xe9 ferm\xe9.","Les documents comptables dont la conservation est l\xe9galement obligatoire sont conserv\xe9s pendant la dur\xe9e pr\xe9vue par la r\xe9glementation, notamment dix ans pour les documents comptables relevant de cette obligation.","Lorsque cela est possible, les donn\xe9es qui ne sont pas n\xe9cessaires au respect de cette obligation sont s\xe9par\xe9es des donn\xe9es conserv\xe9es \xe0 titre comptable.","La fermeture du compte ne permet donc pas de supprimer une facture ou pi\xe8ce comptable qui doit l\xe9galement \xeatre conserv\xe9e."]},{heading:"19. Donn\xe9es fiscales des Professionnels",paragraphs:["Certaines donn\xe9es relatives aux Professionnels peuvent devoir \xeatre conserv\xe9es afin de respecter les obligations fiscales, comptables ou d\xe9claratives applicables \xe0 FOODTECH SOLUTIONS ou aux op\xe9rateurs de plateforme.","Une suppression du Compte Pro ne supprime pas une obligation l\xe9gale de conservation ou de d\xe9claration d\xe9j\xe0 n\xe9e.","Ces informations ne doivent toutefois pas \xeatre r\xe9utilis\xe9es \xe0 des fins incompatibles avec la raison justifiant leur conservation."]},{heading:"20. Avis publi\xe9s",paragraphs:["Les avis constituent des contenus cr\xe9\xe9s par les Clients et associ\xe9s \xe0 leur compte au moment de leur publication.","Lorsqu\u2019un Client supprime son compte, Croki retire les avis publics encore directement associ\xe9s \xe0 ce compte lorsqu\u2019aucune obligation l\xe9gale ou autre justification suffisamment \xe9tablie ne n\xe9cessite leur maintien.","Croki peut conserver une trace technique minimale lorsqu\u2019elle reste n\xe9cessaire \xe0 la lutte contre la fraude, \xe0 la preuve d\u2019une mod\xe9ration, au traitement d\u2019un litige ou \xe0 une obligation l\xe9gale.","Une donn\xe9e r\xe9ellement anonymis\xe9e qui ne permet plus d\u2019identifier la personne ne constitue plus une donn\xe9e personnelle au sens du RGPD, mais Croki veille \xe9galement \xe0 respecter les exigences des plateformes de distribution concernant les contenus cr\xe9\xe9s par l\u2019utilisateur.","Les conditions g\xe9n\xe9rales relatives aux avis sont d\xe9crites dans la Politique des avis clients."]},{heading:"21. R\xe9ponses et contenus professionnels",paragraphs:["Les r\xe9ponses ou contenus cr\xe9\xe9s par un Professionnel peuvent \xeatre supprim\xe9s lorsqu\u2019ils sont directement associ\xe9s \xe0 son compte et ne doivent plus \xeatre maintenus.","Les informations n\xe9cessaires \xe0 la preuve d\u2019une activit\xe9 pass\xe9e ou d\u2019une d\xe9cision de mod\xe9ration peuvent \xeatre conserv\xe9es s\xe9par\xe9ment lorsqu\u2019une justification l\xe9gale ou l\xe9gitime existe.","La fermeture d\u2019un Compte Pro ne doit pas avoir pour effet de rendre une fiche d\u2019\xe9tablissement abandonn\xe9e encore pr\xe9sent\xe9e au public comme une offre commerciale active."]},{heading:"22. Tickets de support",paragraphs:["Les tickets de support qui ne sont plus n\xe9cessaires sont supprim\xe9s selon les r\xe8gles de conservation pr\xe9vues par Croki.","Un ticket peut \xeatre conserv\xe9 temporairement apr\xe8s la suppression du compte lorsqu\u2019il reste n\xe9cessaire au traitement d\u2019une r\xe9clamation, \xe0 la preuve d\u2019un \xe9change, \xe0 la pr\xe9vention d\u2019un abus ou \xe0 la d\xe9fense de droits.","Lorsque l\u2019identit\xe9 directe de la personne n\u2019est plus utile \xe0 cette finalit\xe9, les donn\xe9es sont supprim\xe9es ou anonymis\xe9es dans la mesure appropri\xe9e."]},{heading:"23. Signalements et mod\xe9ration",paragraphs:["Les signalements, d\xe9cisions de mod\xe9ration et informations de s\xe9curit\xe9 ne sont pas n\xe9cessairement supprim\xe9s imm\xe9diatement avec le compte.","Ils peuvent \xeatre conserv\xe9s lorsqu\u2019ils sont n\xe9cessaires \xe0 la preuve du traitement d\u2019un contenu illicite, \xe0 la s\xe9curit\xe9 du Service, \xe0 la pr\xe9vention d\u2019abus, au respect d\u2019une obligation r\xe9glementaire ou \xe0 la d\xe9fense de droits.","La conservation est limit\xe9e aux informations et \xe0 la dur\xe9e n\xe9cessaires \xe0 ces finalit\xe9s."]},{heading:"24. Journaux de s\xe9curit\xe9",paragraphs:["Certains journaux techniques ou de s\xe9curit\xe9 peuvent \xeatre conserv\xe9s pendant une p\xe9riode limit\xe9e apr\xe8s la suppression du compte lorsqu\u2019ils restent n\xe9cessaires \xe0 la s\xe9curit\xe9, \xe0 la d\xe9tection d\u2019abus ou \xe0 l\u2019analyse d\u2019un incident.","Ces journaux sont soumis aux dur\xe9es pr\xe9vues par la Politique de confidentialit\xe9 et ne doivent pas devenir un moyen de conserver ind\xe9finiment le profil complet d\u2019un ancien utilisateur.","Les acc\xe8s \xe0 ces donn\xe9es sont restreints aux personnes habilit\xe9es."]},{heading:"25. Donn\xe9es conserv\xe9es pour un litige",paragraphs:["Lorsqu\u2019un litige, une contestation de paiement, une proc\xe9dure, une r\xe9clamation ou une investigation est en cours, certaines donn\xe9es peuvent \xeatre conserv\xe9es pendant la dur\xe9e n\xe9cessaire \xe0 son traitement.","Les donn\xe9es conserv\xe9es pour cette finalit\xe9 sont limit\xe9es \xe0 celles n\xe9cessaires \xe0 la constatation, \xe0 l\u2019exercice ou \xe0 la d\xe9fense des droits concern\xe9s.","Une fois cette justification disparue et les d\xe9lais applicables expir\xe9s, les donn\xe9es sont supprim\xe9es ou anonymis\xe9es."]},{heading:"26. Prestataires de Croki",paragraphs:["La suppression ne concerne pas uniquement la base de donn\xe9es principale de Croki.","Lorsque des donn\xe9es personnelles associ\xe9es au compte sont trait\xe9es pour le compte de FOODTECH SOLUTIONS par ses prestataires, FOODTECH SOLUTIONS applique ou transmet les instructions n\xe9cessaires pour supprimer ou anonymiser les donn\xe9es qui ne doivent plus \xeatre conserv\xe9es.","Cela peut notamment concerner, selon les donn\xe9es effectivement trait\xe9es, les prestataires d\u2019h\xe9bergement, d\u2019authentification, de stockage, de communications ou d\u2019autres services utilis\xe9s par Croki.","Certains prestataires peuvent n\xe9anmoins devoir conserver certaines informations pour leurs propres obligations l\xe9gales lorsqu\u2019ils agissent eux-m\xeames comme responsables du traitement pour les op\xe9rations concern\xe9es."]},{heading:"27. Sauvegardes",paragraphs:["Certaines donn\xe9es peuvent subsister temporairement dans des sauvegardes techniques apr\xe8s leur suppression des syst\xe8mes actifs.","Ces sauvegardes sont prot\xe9g\xe9es, soumises \xe0 un cycle de conservation d\xe9fini et ne doivent pas \xeatre utilis\xe9es pour r\xe9tablir volontairement un compte supprim\xe9 dans le fonctionnement normal du Service.","Lorsqu\u2019une sauvegarde ancienne doit \xeatre restaur\xe9e pour des raisons techniques, Croki met en \u0153uvre des m\xe9canismes permettant de respecter de nouveau les suppressions d\xe9j\xe0 enregistr\xe9es."]},{heading:"28. D\xe9lais de traitement",paragraphs:["Une suppression technique peut \xeatre r\xe9alis\xe9e rapidement lorsque la situation du compte permet son ex\xe9cution imm\xe9diate.","Lorsque la demande constitue \xe9galement l\u2019exercice d\u2019un droit \xe0 l\u2019effacement au sens du RGPD, FOODTECH SOLUTIONS la traite dans les meilleurs d\xe9lais et en principe au plus tard dans le d\xe9lai l\xe9gal d\u2019un mois.","Ce d\xe9lai peut \xeatre prolong\xe9 de deux mois suppl\xe9mentaires lorsque la complexit\xe9 ou le nombre de demandes le justifie.","La personne concern\xe9e est alors inform\xe9e de la prolongation et de ses motifs dans le premier mois.","Les donn\xe9es qui doivent \xeatre l\xe9galement conserv\xe9es ne sont pas maintenues comme donn\xe9es actives uniquement parce que le traitement de la demande a \xe9t\xe9 cl\xf4tur\xe9."]},{heading:"29. Confirmation de la suppression",paragraphs:["Lorsque la demande a \xe9t\xe9 trait\xe9e et que le compte a \xe9t\xe9 supprim\xe9, Croki informe l\u2019utilisateur lorsque FOODTECH SOLUTIONS dispose encore d\u2019un moyen appropri\xe9 de le contacter.","La confirmation indique que le compte a \xe9t\xe9 supprim\xe9 et peut pr\xe9ciser que certaines cat\xe9gories limit\xe9es de donn\xe9es restent conserv\xe9es lorsque la loi ou une autre justification valable l\u2019impose.","Croki \xe9vite d\u2019envoyer dans cette confirmation des informations personnelles suppl\xe9mentaires qui ne seraient pas n\xe9cessaires."]},{heading:"30. Donn\xe9es que Croki ne peut pas effacer imm\xe9diatement",paragraphs:["Une demande de suppression ne signifie pas que FOODTECH SOLUTIONS doit d\xe9truire toute information imm\xe9diatement et sans exception.","Le droit \xe0 l\u2019effacement conna\xeet notamment des limites lorsqu\u2019une conservation est n\xe9cessaire pour respecter une obligation l\xe9gale ou pour constater, exercer ou d\xe9fendre des droits en justice.","Lorsque FOODTECH SOLUTIONS conserve certaines donn\xe9es malgr\xe9 la suppression du compte, elle limite leur utilisation \xe0 la finalit\xe9 justifiant cette conservation.","Les donn\xe9es sont supprim\xe9es ou anonymis\xe9es lorsque cette justification cesse d\u2019exister."]},{heading:"31. Suppression et anonymisation",paragraphs:["Croki peut recourir \xe0 l\u2019anonymisation lorsqu\u2019il n\u2019est plus n\xe9cessaire de conserver l\u2019identit\xe9 d\u2019une personne mais qu\u2019une information statistique ou technique non personnelle reste utile.","Pour \xeatre consid\xe9r\xe9e comme anonymis\xe9e, une donn\xe9e ne doit plus permettre d\u2019identifier la personne concern\xe9e par des moyens raisonnablement susceptibles d\u2019\xeatre utilis\xe9s.","Le simple remplacement du nom par un identifiant interne r\xe9versible constitue une pseudonymisation et non n\xe9cessairement une anonymisation.","Les donn\xe9es pseudonymis\xe9es restent prot\xe9g\xe9es comme donn\xe9es personnelles lorsqu\u2019une r\xe9identification demeure possible."]},{heading:"32. Cr\xe9er un nouveau compte ult\xe9rieurement",paragraphs:["La suppression d\u2019un compte ne garantit pas qu\u2019un nouvel utilisateur puisse r\xe9utiliser imm\xe9diatement chaque identifiant ou information pr\xe9c\xe9demment associ\xe9 au compte.","Certaines protections de s\xe9curit\xe9 ou contraintes techniques peuvent temporairement emp\xeacher la r\xe9utilisation imm\xe9diate de certaines informations.","Lorsqu\u2019une nouvelle inscription est autoris\xe9e, elle cr\xe9e un nouveau compte et ne r\xe9active pas automatiquement l\u2019ancien historique supprim\xe9."]},{heading:"33. Sign in with Apple",paragraphs:["Si Croki propose \xe0 l\u2019avenir la cr\xe9ation ou l\u2019authentification d\u2019un compte au moyen de Sign in with Apple, la suppression du compte Croki entra\xeenera \xe9galement la r\xe9vocation des jetons Sign in with Apple concern\xe9s conform\xe9ment aux exigences d\u2019Apple.","Cette section ne signifie pas que Sign in with Apple est actuellement activ\xe9 lorsqu\u2019il ne l\u2019est pas dans Croki."]},{heading:"34. Suppression sur Google Play",paragraphs:["Pour la version Android distribu\xe9e sur Google Play, Croki fournit une possibilit\xe9 facilement identifiable de demander la suppression du compte depuis l\u2019application.","Croki fournit \xe9galement la pr\xe9sente ressource Web publique afin qu\u2019une personne puisse demander la suppression sans devoir r\xe9installer l\u2019application.","La page Web indique clairement le service et l\u2019\xe9diteur concern\xe9s et propose un moyen effectif de d\xe9poser une demande de suppression.","Une simple d\xe9sactivation ou suspension du compte ne constitue pas une suppression."]},{heading:"35. Suppression sur l\u2019App Store",paragraphs:["Pour les applications Apple permettant la cr\xe9ation d\u2019un compte Croki, une fonction permettant d\u2019initier la suppression est disponible directement dans l\u2019application.","La fonction est facilement identifiable dans les param\xe8tres ou la gestion du compte.","Croki peut pr\xe9voir une confirmation ou une r\xe9authentification afin d\u2019\xe9viter une suppression accidentelle ou frauduleuse, sans imposer un parcours inutilement complexe.","La suppression porte sur le compte et les donn\xe9es associ\xe9es qui ne doivent pas \xeatre l\xe9galement conserv\xe9es."]},{heading:"36. Droit \xe0 l\u2019effacement",paragraphs:["La fonction de suppression du compte Croki compl\xe8te, mais ne remplace pas, le droit \xe0 l\u2019effacement pr\xe9vu par le RGPD.","Vous pouvez demander l\u2019effacement de certaines donn\xe9es sans n\xe9cessairement supprimer l\u2019int\xe9gralit\xe9 de votre compte lorsqu\u2019un tel droit est applicable.","Inversement, la suppression du compte n\u2019implique pas automatiquement l\u2019effacement des donn\xe9es qui doivent l\xe9galement ou l\xe9gitimement \xeatre conserv\xe9es.","Les autres droits et les modalit\xe9s permettant de les exercer sont d\xe9crits dans la page \xab G\xe9rer mes donn\xe9es et exercer mes droits \xbb."]},{heading:"37. Si vous n\u2019avez plus acc\xe8s \xe0 votre compte",paragraphs:["La perte d\u2019acc\xe8s \xe0 un compte ne vous emp\xeache pas de demander sa suppression.","Vous pouvez utiliser le formulaire public disponible sur cette page ou contacter FOODTECH SOLUTIONS.","Croki vous demandera uniquement les informations raisonnablement n\xe9cessaires afin de retrouver le compte et v\xe9rifier que vous \xeates autoris\xe9 \xe0 demander sa suppression.","Il ne vous sera pas demand\xe9 de r\xe9installer l\u2019application uniquement pour d\xe9poser votre demande."]},{heading:"38. Si Croki refuse ou diff\xe8re une suppression",paragraphs:["Lorsque la suppression ne peut pas \xeatre ex\xe9cut\xe9e imm\xe9diatement, FOODTECH SOLUTIONS explique la raison de cette situation.","Lorsqu\u2019une donn\xe9e doit continuer \xe0 \xeatre conserv\xe9e malgr\xe9 une demande d\u2019effacement, FOODTECH SOLUTIONS pr\xe9cise le principe justifiant cette conservation lorsque cela est requis.","Une impossibilit\xe9 de supprimer certaines donn\xe9es ne permet pas de conserver indistinctement toutes les autres donn\xe9es du compte.","Croki doit supprimer ou anonymiser les autres donn\xe9es qui n\u2019ont plus de justification de conservation."]},{heading:"39. R\xe9clamation aupr\xe8s de la CNIL",paragraphs:["Si vous estimez que FOODTECH SOLUTIONS ne respecte pas vos droits concernant la suppression ou l\u2019effacement de vos donn\xe9es personnelles, vous pouvez introduire une r\xe9clamation aupr\xe8s de la Commission nationale de l\u2019informatique et des libert\xe9s (CNIL).","Commission nationale de l\u2019informatique et des libert\xe9s \u2014 3 Place de Fontenoy, TSA 80715, 75334 Paris Cedex 07, France \u2014 www.cnil.fr.","Vous pouvez contacter FOODTECH SOLUTIONS avant d\u2019effectuer cette d\xe9marche afin de tenter de r\xe9soudre la difficult\xe9, sans que cette possibilit\xe9 ne limite votre droit de saisir la CNIL."]},{heading:"40. Contact",paragraphs:[`Responsable : ${n.LEGAL_OPERATOR_NAME}.`,`Service : ${n.LEGAL_TRADE_NAME}.`,`Adresse : ${n.LEGAL_SLOT.registeredOffice}.`,`E-mail : ${n.LEGAL_SLOT.email}.`,`T\xe9l\xe9phone : ${n.LEGAL_SLOT.phone}.`]}]})},1537,[1630,1228]);